function toast(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),2300)}
function currentOrder(){if(!state.order){const regular=Math.random()<Math.min(.55,.18+state.rep/180),need=1+(state.rep>35&&Math.random()>.72?1:0),quality=30+Math.floor(Math.random()*20);state.order={name:['Milo','Nessa','Rafi','Tess','Ollie'][Math.floor(Math.random()*5)],face:['🧢','🧣','🧑🏽‍🦱','👩🏻‍🎤','🧔🏽'][Math.floor(Math.random()*5)],need,quality,reward:Math.round((48+Math.floor(state.rep/4)+Math.floor(Math.random()*15))*(regular?1.18:1)),regular};state.orderAge=0}}
function level(){return properties[Math.min(state.stage,properties.length-1)]}function plantDuration(){return Math.max(12,30-(state.upgrades.includes('lamp')?7:0))}
function plant(){const cap=level().slots+(state.upgrades.includes('shelf')?2:0)+(state.crew.includes('helper')?1:0);if(state.plants.length>=cap){toast('No room for another cutting. Try an upgrade.');return}if(state.cash<12){toast('You need $12 for a cutting.');return}state.cash-=12;state.plants.push({progress:0,quality:48+Math.floor(Math.random()*14)});toast('Cutting planted. Keep an eye on it.');render()}
function harvest(){const ready=state.plants.filter(p=>p.progress>=1);if(!ready.length){toast('Nothing ready just yet. Give them a little time.');return}let q=0;ready.forEach(p=>{q+=p.quality+(state.upgrades.includes('soil')?12:0)});state.stock+=ready.length;state.quality=Math.round((state.quality*Math.max(0,state.stock-ready.length)+q)/state.stock);state.plants=state.plants.filter(p=>p.progress<1);state.actions++;toast(`${ready.length} fresh ${ready.length===1?'pack':'packs'} added to inventory.`);if(state.actions%4===0)state.day++;render()}
function sell(){currentOrder();const o=state.order;if(state.stock<o.need){toast('Not enough in stock for this request. Try a quick market sale or grow more.');return}if(state.quality<o.quality){toast('This customer wants better quality. Keep growing or use the market.');return}if(state.heat>=75&&Math.random()<.25){state.heat=Math.max(0,state.heat-8);toast('The handoff is delayed. Attention cools a little.');render();return}const bonus=state.upgrades.includes('manager')?Math.round(o.reward*.15):0,total=o.reward+bonus;state.stock-=o.need;state.cash+=total;state.rep+=5+(state.upgrades.includes('sign')?3:0);state.heat=Math.min(maxHeat,state.heat+(state.fronts.includes('ledger')?1:4));state.order=null;state.orderAge=0;state.day+=Math.random()>.55?1:0;toast(`Request fulfilled. +$${total} · reputation up.`);currentOrder();render();persist()}
 function quickSell(){if(state.stock<1){toast('No packs in stock to take to market.');return}const price=25+Math.round(state.quality*.45)+Math.floor(state.rep/12),bonus=state.upgrades.includes('manager')?Math.round(price*.15):0;state.stock--;state.cash+=price+bonus;state.heat=Math.min(maxHeat,state.heat+1);state.day+=Math.random()>.8?1:0;toast(`Market sale · 1 pack moved for $${price+bonus}.`);render();persist()}
 function passOrder(){state.order=null;state.orderAge=0;currentOrder();toast('You pass on that request. A new customer steps up.');render();persist()}
function buy(id,cost,group){if(state.upgrades.includes(id)||state.crew.includes(id)||state.fronts.includes(id))return;if(state.cash<cost){toast('Not enough cash for that yet.');return}state.cash-=cost;if(group==='crew')state.crew.push(id);else if(group==='front')state.fronts.push(id);else state.upgrades.push(id);if(id==='helper')state.rep+=5;toast('Investment made. Your operation grows.');render()}
function expand(){const p=properties[state.stage+1],cost=level().price;if(!p||state.cash<cost)return;state.cash-=cost;state.stage++;state.day+=3;state.heat=Math.min(maxHeat,state.heat+8);toast(`Welcome to ${p.name}. New chapter unlocked.`);render()}
