document.querySelectorAll('.tab').forEach(t=>t.onclick=()=>{state.tab=t.dataset.tab;document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===t));render()});
$('storyBtn').onclick=()=>openStory();$('modalClose').onclick=()=>$('modalBack').classList.remove('open');$('modalBack').onclick=e=>{if(e.target===$('modalBack'))$('modalBack').classList.remove('open')};
function openStory(){const m=missions[Math.min(state.mission,missions.length-1)];$('modalEyebrow').textContent=`FIELD NOTES · ${String(state.mission+1).padStart(2,'0')}`;$('modalTitle').textContent=m.title;$('modalCopy').textContent=m.detail;$('modalChoices').innerHTML='';m.choices.forEach(([label,desc,fn])=>{const b=document.createElement('button');b.innerHTML=`${label}<br><small style="font-weight:500;color:#78867d">${desc}</small>`;b.onclick=()=>{fn();state.mission=Math.min(state.mission+1,missions.length);$('modalBack').classList.remove('open');toast('Choice made. The story moves on.');render();persist()};$('modalChoices').append(b)});$('modalBack').classList.add('open')}
const canvas=$('scene'),ctx=canvas.getContext('2d');let time=0;const camera={x:0,y:0,zoom:1,rotation:0};let pointer=null,dragged=false;

