.storycard{background:#21332d;color:#eef3e7;border:0;position:relative;overflow:hidden;padding:18px}
.storycard:after{content:"✳";position:absolute;right:12px;top:8px;font-size:54px;color:#ffffff0b}
.storycard h3{font-size:17px;margin:8px 0}
.storycard p{color:#c2d0c3;font-size:11px;line-height:1.55;margin:0 0 12px;max-width:90%}
.storycard button{background:#c9e982;border-radius:9px;padding:9px 12px;font-size:10px;font-weight:900}
.storycard{grid-column:1/-1}
.storycard{grid-column:auto}
.storycard{border-radius:9px}
.storycard{background:#202522;border:1px solid #343c36;border-radius:4px;box-shadow:0 5px 16px #0002}
.storycard h3{color:#e0ddcd}
.storycard p,.statline,.uptext small,.order-info small{color:#a7aaa0}
.storycard button{background:#353b32;color:#d8c99e;border-radius:3px}

input.newString:
.storycard button{background:#353b32;color:#d8c99e;border-radius:3px}
.mission-objective{background:#ffffff08;border:1px solid #ffffff12;border-radius:4px;padding:8px 9px 9px;margin:0 0 12px}
.mission-objective span{display:block;font-size:7px;letter-spacing:.2em;color:#9a987d;font-weight:900;margin-bottom:4px}
.mission-objective strong{display:block;font-size:10px;color:#d8cfae;font-weight:700;line-height:1.35}
.mission-track{height:4px;background:#343a33;border-radius:1px;margin-top:7px;overflow:hidden}
.mission-track i{display:block;height:100%;width:0;background:linear-gradient(90deg,#7f9870,#c79559);transition:width .4s}
@media(max-width:700px){.mission-objective{padding:6px 7px 7px}.mission-objective strong{font-size:9px}}

