  function quickSell(){if(state.stock<1){toast('No packs in stock to take to market.');return}const basePrice=25+Math.round(state.quality*.45)+Math.floor(state.rep/12),price=state.fronts.includes('market')?Math.round(basePrice*1.25):basePrice,bonus=state.upgrades.includes('manager')?Math.round(price*.15):0;state.stock--;state.cash+=price+bonus;state.milestones.sales++;state.heat=Math.min(maxHeat,state.heat+1);state.day+=Math.random()>.8?1:0;toast(`Market sale · 1 pack moved for $${price+bonus}.`);render();persist()}
  function passOrder(){state.order=null;state.orderAge=0;currentOrder();toast('You pass on that request. A new customer steps up.');render();persist()}
 function buy(id,cost,group){if(state.upgrades.includes(id)||state.crew.includes(id)||state.fronts.includes(id))return;if(state.cash<cost){toast('Not enough cash for that yet.');return}state.cash-=cost;if(group==='crew')state.crew.push(id);else if(group==='front')state.fronts.push(id);else state.upgrades.push(id);state.milestones.investments++;if(id==='helper')state.rep+=5;toast('Investment made. Your operation grows.');render()}
 function expand(){const p=properties[state.stage+1],cost=level().price;if(!p||state.cash<cost)return;state.cash-=cost;state.stage++;state.day+=3;state.heat=Math.min(maxHeat,state.heat+8);toast(`Welcome to ${p.name}. New chapter unlocked.`);render()}
