 const o=state.order,remaining=Math.max(0,Math.ceil(orderLifetime-state.orderAge));$('customerName').textContent=`${o.name} wants ${o.need===1?'a sampler':`${o.need} packs`}`;$('customerFace').textContent=o.face;$('orderNeed').textContent=`Need ${o.need} ${o.need===1?'pack':'packs'} · Quality ${o.quality}+${o.regular?' · neighborhood regular':''}`;$('orderReward').textContent='+$'+o.reward;$('orderTimer').textContent=`${remaining}s TO DECIDE`;$('sellBtn').disabled=state.stock<o.need||state.quality<o.quality;$('sellBtn').textContent=state.stock<o.need?'Need stock':state.quality<o.quality?'Quality low':'Fulfill · $'+o.reward;$('quickSellBtn').disabled=state.stock<1;$('quickSellBtn').textContent=state.stock?`Market · $${25+Math.round(state.quality*.45)+Math.floor(state.rep/12)}`:'Market sale';$('passBtn').disabled=false;$('orderProgress').style.width=Math.max(0,100-(state.orderAge/orderLifetime)*100)+'%';$('missionNo').textContent=state.mission>=missions.length?'EPILOGUE':String(state.mission+1).padStart(2,'0')+' / '+String(missions.length).padStart(2,'0');let m=missions[Math.min(state.mission,missions.length-1)],missionDone=state.mission>=missions.length,progress=missionDone?1:missionProgress(m);$('storyTitle').textContent=missionDone?'An Empire of Your Own':m.title;$('storyText').textContent=missionDone?'You built a citywide garden network, one neighbor at a time. Your crew has already started planning the next season.':m.text;$('missionObjective').textContent=missionDone?'Campaign complete · the next season is yours':`${m.goal.label} · ${Math.floor(progress*m.goal.target)}/${m.goal.target}`;$('missionProgress').style.width=(progress*100)+'%';$('plantCost').textContent=state.plants.length>=cap?'Room full':'$12 · '+(cap-state.plants.length)+' spaces';$('plantBtn').disabled=state.plants.length>=cap||state.cash<12;$('harvestHint').textContent=state.plants.some(x=>x.progress>=1)?`${state.plants.filter(x=>x.progress>=1).length} ready to collect`:`${state.plants.length} growing`;$('harvestBtn').disabled=!state.plants.some(x=>x.progress>=1);$('upgradeList').innerHTML='';
